import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor batchnorm2d_forward(torch::Tensor x,
                                   torch::Tensor weight,
                                   torch::Tensor bias,
                                   torch::Tensor running_mean,
                                   torch::Tensor running_var,
                                   double eps,
                                   double momentum,
                                   bool training);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void batchnorm2d_kernel(
    const T* __restrict__ X,
    T* __restrict__ Y,
    const T* __restrict__ weight,
    const T* __restrict__ bias,
    T* __restrict__ running_mean,
    T* __restrict__ running_var,
    int N, int C, int H, int W,
    float eps, float momentum)
{
    int c = blockIdx.x;
    int HW = H * W;
    int64_t count = (int64_t)N * (int64_t)HW;
    int64_t channel_stride = (int64_t)C * (int64_t)HW;

    // Per-channel view: shape (N, HW), stride (C*HW, 1)
    auto mX = make_tensor(make_gmem_ptr(X + (int64_t)c * (int64_t)HW),
                           make_shape((int64_t)N, (int64_t)HW),
                           make_stride(channel_stride, Int<1>{}));
    auto mY = make_tensor(make_gmem_ptr(Y + (int64_t)c * (int64_t)HW),
                           make_shape((int64_t)N, (int64_t)HW),
                           make_stride(channel_stride, Int<1>{}));

    int tid = threadIdx.x;
    int nthreads = blockDim.x;

    float sum = 0.f, sumsq = 0.f;

    for (int64_t idx = tid; idx < count; idx += nthreads) {
        int64_t n  = idx / HW;
        int64_t hw = idx - n * HW;
        float v = static_cast<float>(mX(n, hw));
        sum   += v;
        sumsq += v * v;
    }

    extern __shared__ float sdata[];
    float* ssum   = sdata;
    float* ssumsq = sdata + nthreads;

    ssum[tid]   = sum;
    ssumsq[tid] = sumsq;
    __syncthreads();

    for (int s = nthreads / 2; s > 0; s >>= 1) {
        if (tid < s) {
            ssum[tid]   += ssum[tid + s];
            ssumsq[tid] += ssumsq[tid + s];
        }
        __syncthreads();
    }

    __shared__ float mean_s, invstd_s;
    if (tid == 0) {
        float total_sum   = ssum[0];
        float total_sumsq = ssumsq[0];
        float m   = total_sum / (float)count;
        float var = total_sumsq / (float)count - m * m; // biased variance
        if (var < 0.f) var = 0.f;
        mean_s   = m;
        invstd_s = rsqrtf(var + eps);

        float unbiased_var = (count > 1) ? (var * (float)count / (float)(count - 1)) : var;
        running_mean[c] = (T)((1.0f - momentum) * (float)running_mean[c] + momentum * m);
        running_var[c]  = (T)((1.0f - momentum) * (float)running_var[c]  + momentum * unbiased_var);
    }
    __syncthreads();

    float mean   = mean_s;
    float invstd = invstd_s;
    float w = (weight != nullptr) ? static_cast<float>(weight[c]) : 1.0f;
    float b = (bias   != nullptr) ? static_cast<float>(bias[c])   : 0.0f;

    for (int64_t idx = tid; idx < count; idx += nthreads) {
        int64_t n  = idx / HW;
        int64_t hw = idx - n * HW;
        float v = static_cast<float>(mX(n, hw));
        float y = (v - mean) * invstd * w + b;
        mY(n, hw) = static_cast<T>(y);
    }
}
template <typename T>
__global__ void batchnorm2d_eval_kernel(
    const T* __restrict__ X,
    T* __restrict__ Y,
    const T* __restrict__ weight,
    const T* __restrict__ bias,
    const T* __restrict__ running_mean,
    const T* __restrict__ running_var,
    int N, int C, int H, int W,
    float eps)
{
    int c = blockIdx.x;
    int HW = H * W;
    int64_t count = (int64_t)N * (int64_t)HW;
    int64_t channel_stride = (int64_t)C * (int64_t)HW;
    auto mX = make_tensor(make_gmem_ptr(X + (int64_t)c * (int64_t)HW),
                           make_shape((int64_t)N, (int64_t)HW),
                           make_stride(channel_stride, Int<1>{}));
    auto mY = make_tensor(make_gmem_ptr(Y + (int64_t)c * (int64_t)HW),
                           make_shape((int64_t)N, (int64_t)HW),
                           make_stride(channel_stride, Int<1>{}));
    int tid = threadIdx.x;
    int nthreads = blockDim.x;
    float mean = static_cast<float>(running_mean[c]);
    float var  = static_cast<float>(running_var[c]);
    float invstd = rsqrtf(var + eps);
    float w = (weight != nullptr) ? static_cast<float>(weight[c]) : 1.0f;
    float b = (bias   != nullptr) ? static_cast<float>(bias[c])   : 0.0f;
    for (int64_t idx = tid; idx < count; idx += nthreads) {
        int64_t n  = idx / HW;
        int64_t hw = idx - n * HW;
        float v = static_cast<float>(mX(n, hw));
        float y = (v - mean) * invstd * w + b;
        mY(n, hw) = static_cast<T>(y);
    }
}
torch::Tensor batchnorm2d_forward(torch::Tensor x,
                                   torch::Tensor weight,
                                   torch::Tensor bias,
                                   torch::Tensor running_mean,
                                   torch::Tensor running_var,
                                   double eps,
                                   double momentum,
                                   bool training) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(x.dim() == 4, "x must be [N, C, H, W]");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();
    auto b_c = bias.contiguous();
    auto rm_c = running_mean.contiguous();
    auto rv_c = running_var.contiguous();
    int N = (int)x_c.size(0);
    int C = (int)x_c.size(1);
    int H = (int)x_c.size(2);
    int W = (int)x_c.size(3);
    TORCH_CHECK(w_c.size(0) == C, "weight size mismatch");
    TORCH_CHECK(b_c.size(0) == C, "bias size mismatch");
    TORCH_CHECK(rm_c.size(0) == C, "running_mean size mismatch");
    TORCH_CHECK(rv_c.size(0) == C, "running_var size mismatch");
    auto y = torch::empty_like(x_c);
    const int threads = 256;
    dim3 block(threads);
    dim3 grid(C);
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    if (training) {
        size_t shmem = 2 * threads * sizeof(float);
        batchnorm2d_kernel<float><<<grid, block, shmem, stream>>>(
            x_c.data_ptr<float>(),
            y.data_ptr<float>(),
            w_c.data_ptr<float>(),
            b_c.data_ptr<float>(),
            rm_c.data_ptr<float>(),
            rv_c.data_ptr<float>(),
            N, C, H, W,
            (float)eps, (float)momentum
        );
    } else {
        batchnorm2d_eval_kernel<float><<<grid, block, 0, stream>>>(
            x_c.data_ptr<float>(),
            y.data_ptr<float>(),
            w_c.data_ptr<float>(),
            b_c.data_ptr<float>(),
            rm_c.data_ptr<float>(),
            rv_c.data_ptr<float>(),
            N, C, H, W,
            (float)eps
        );
    }
    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "batchnorm2d_kernel launch failed: ", cudaGetErrorString(err));
    if (training) {
        // copy updated running stats back into the passed tensors (in case they were not the same storage)
        running_mean.copy_(rm_c);
        running_var.copy_(rv_c);
    }
    return y;
}
"""

bn_ext = load_inline(
    name="cute_batchnorm2d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["batchnorm2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Batch Normalization implemented with a custom CUDA/CuTe kernel.
    """
    def __init__(self, num_features: int):
        super().__init__()
        self.num_features = num_features
        self.eps = 1e-5
        self.momentum = 0.1

        self.weight = nn.Parameter(torch.ones(num_features))
        self.bias = nn.Parameter(torch.zeros(num_features))

        self.register_buffer("running_mean", torch.zeros(num_features))
        self.register_buffer("running_var", torch.ones(num_features))
        self.register_buffer("num_batches_tracked", torch.tensor(0, dtype=torch.long))

        self._ext = bn_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.cuda().contiguous().float()
        out = self._ext.batchnorm2d_forward(
            x,
            self.weight,
            self.bias,
            self.running_mean,
            self.running_var,
            float(self.eps),
            float(self.momentum),
            bool(self.training),
        )
        if self.training:
            self.num_batches_tracked += 1
        return out

